<?php
if (!defined('ABSPATH')) { exit; }
/** Authenticated company review handler. No browser credentials. */
final class WGPP_Reviews {
    public static function ready() {
        $c=WGPP_Company::context();
        return $c && apply_filters('wgpp_review_service_ready',false,$c['id'])===true;
    }
    public static function ajax() {
        if (!WGPP_Company::can('view')) { wp_send_json_error(['message'=>'Company access required.'],403); return; }
        check_ajax_referer('wgpp_analytics','nonce');
        nocache_headers();
        if (!self::ready()) { wp_send_json_error(['message'=>'Pro Analytics Review is not available.'],503); return; }
        try {
            $c=WGPP_Company::context();
            $op=$_REQUEST['operation'] ?? '';
            if (!is_string($op) || !in_array($op,['preview','list','get','status','generate'],true)) { throw new InvalidArgumentException('Invalid review action.'); }
            if (in_array($op,['preview','generate'],true) && !WGPP_Company::can('review')) { wp_send_json_error(['message'=>'An owner or analyst must request a new evaluation.'],403); return; }
            $request=[];
            if (in_array($op,['get','status'],true)) {
                $id=$_REQUEST['report_id'] ?? '';
                if (!is_string($id) || !preg_match('/^[a-zA-Z0-9-]{1,100}$/D',$id)) { throw new InvalidArgumentException('Invalid report reference.'); }
                $request['report_id']=$id;
            }
            if ($op==='generate') {
                if (($_SERVER['REQUEST_METHOD'] ?? '')!=='POST' || ($_POST['confirmed'] ?? '')!=='1') { throw new InvalidArgumentException('Confirm use of one review.'); }
                $id=$_POST['request_id'] ?? '';
                if (!is_string($id) || !preg_match('/^[a-zA-Z0-9-]{16,100}$/D',$id)) { throw new InvalidArgumentException('Invalid generation request.'); }
                $q=[];
                foreach(['preset','end','start','comparison'] as $key) {
                    if (!is_string($_POST[$key] ?? null)) { throw new InvalidArgumentException('Invalid date selection.'); }
                    $q[$key]=sanitize_text_field(wp_unslash($_POST[$key]));
                }
                $ranges=WGPP_Analytics::ranges($q['preset'],$q['end'],$q['start'],$q['comparison']);
                if($ranges['comparison']===null){throw new InvalidArgumentException('Select a comparison period to request a movement review.');}
                $current=WGPP_Analytics::lookup(...$ranges['current']);
                $comparison=WGPP_Analytics::lookup(...$ranges['comparison']);
                if (!$current || !$comparison) { throw new InvalidArgumentException('Both reporting periods need data before requesting an evaluation.'); }
                if ($current['property']!==$comparison['property'] || $current['timezone']!==$comparison['timezone']) { throw new InvalidArgumentException('Comparison property or timezone differs.'); }
                $request=['request_id'=>$id,'confirmed'=>true,'snapshot'=>[
                    'ranges'=>$ranges,'current'=>$current,'comparison'=>$comparison,
                    'analysis'=>WGPP_Analytics::analyse($current,$comparison),
                    'context'=>WGPP_Pro_Review::capture($c['id'],$ranges,$current)]];
            }
            // Adapter must authenticate to hosted service and resolve billing there.
            // Company, principal and role always come from verified server context.
            $response=apply_filters('wgpp_review_service',null,$op,
                ['company_id'=>$c['id'],'principal'=>get_current_user_id(),'role'=>$c['role']],$request);
            if ($response===null || is_wp_error($response)) { wp_send_json_error(['message'=>'Review service unavailable. No evaluation was confirmed.'],503); return; }
            if (!is_array($response)) { throw new InvalidArgumentException('Unexpected review response.'); }
            wp_send_json_success($response);
        } catch (InvalidArgumentException $e) { wp_send_json_error(['message'=>$e->getMessage()],422); }
        catch (RuntimeException $e) { wp_send_json_error(['message'=>$e->getMessage()],503); }
    }
}

/** Evidence-led Pro Analytics Review. Rules are usable without an external AI account. */
final class WGPP_Pro_Review {
    const OPTION='_wgpp_pro_review_ai_v1';
    public static function boot(){
        add_filter('wgpp_evaluator_ready',static function(){return true;},20);
        add_filter('wgpp_evaluate_snapshot',[__CLASS__,'evaluate'],20,3);
        add_action('admin_menu',static function(){add_management_page('Pro Analytics Review settings','Pro Analytics Review settings','manage_options','wgpp-pro-review',[__CLASS__,'settings_page']);});
        add_action('admin_post_wgpp_review_settings',[__CLASS__,'save_settings']);
    }
    private static function settings(){try{$v=get_option(self::OPTION);return $v?WGPP_Google::decrypt($v,'pro-review:application'):[];}catch(RuntimeException $e){return [];}}
    public static function save_settings(){
        if(!current_user_can('manage_options')){wp_die('Administrator access required.','',['response'=>403]);}check_admin_referer('wgpp_review_settings');
        $old=self::settings();$key=$_POST['review_key'] ?? '';$model=$_POST['review_model'] ?? '';
        if(!is_string($key)||!is_string($model)){wp_die('Invalid settings.');}$key=trim(wp_unslash($key));$model=trim(wp_unslash($model));
        if(!preg_match('/^[a-zA-Z0-9._:-]{1,100}$/D',$model)||($key!=='' && (strlen($key)<20||strlen($key)>1000||preg_match('/\s/',$key)))){wp_die('Enter a valid model ID and API key.');}
        $data=['model'=>$model,'key'=>$key ?: ($old['key'] ?? ''),'enabled'=>isset($_POST['review_ai_enabled'])];
        update_option(self::OPTION,WGPP_Google::encrypt($data,'pro-review:application'),false);
        wp_safe_redirect(admin_url('admin.php?page=wgpp-pro-review&saved=1'));exit;
    }
    public static function settings_page(){
        if(!current_user_can('manage_options')){return;}$s=self::settings();
        echo '<div class="wrap"><h1>Pro Analytics Review settings</h1><p>The analytical Pro Analytics Review works without an AI key. Optional AI enhancement sends the selected company’s aggregate analytics, public website excerpt, and available social/email results to OpenAI. It does not send connection credentials or contact lists.</p><p>Current mode: <strong>'.(!empty($s['enabled'])&&!empty($s['key'])?'AI enhanced':'Analytical').'</strong>. API key: '.(!empty($s['key'])?'Stored securely':'Not configured').'.</p>';
        if(isset($_GET['saved'])){echo '<p>Settings saved.</p>';}
        echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('wgpp_review_settings');
        echo '<input type="hidden" name="action" value="wgpp_review_settings"><p><label><input type="checkbox" name="review_ai_enabled" '.(!empty($s['enabled'])?'checked':'').'> Enable AI enhancement</label></p><p><label>OpenAI model ID <input name="review_model" value="'.esc_attr($s['model'] ?? 'gpt-4.1-mini').'" required></label></p><p><label>OpenAI API key <input type="password" name="review_key" value="" autocomplete="new-password" size="50"></label><br>Leave blank to retain the stored key. Never share it in chat.</p><button class="button button-primary">Save Pro Analytics Review settings</button></form><p>Paid Pro companies receive four reviews per monthly subscription anniversary window, including annual plans. Preview workspaces use the calendar month in America/Chicago.</p></div>';
        WGPP_Native_Reviews::reset_controls();
        $sync=get_option('_wgpp_pro_curriculum_sync');echo '<h2>Pro membership and course access</h2><p>Monthly and annual Pro memberships grant the paying owner course access. Invited analytics seats do not receive WishList course levels. The company remains tied to its original payer after an owner reassignment.</p>';
        if($sync){echo '<p>Course access synchronized: '.(int)$sync['count'].' pages · '.esc_html($sync['at']).'.</p>';}
        echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('wgpp_sync_curriculum');echo '<input type="hidden" name="action" value="wgpp_sync_curriculum"><button class="button">Sync full Live Campaign curriculum to Pro memberships</button></form>';
    }
    public static function capture($company,$ranges,$current){
        $brand=WGPP_Company::brand($company);$out=['smm_foundation'=>self::foundation(),'company'=>$current['company'] ?? get_the_title($company),'website'=>$brand['website'] ?? $current['website'] ?? '', 'service_area'=>$brand['service_area'] ?? [],'social_profiles'=>$brand['social'] ?? [],'captured_at'=>gmdate('c'),'channels'=>[]];
        // Only normalized reports are retained. Provider token envelopes never enter a review.
        foreach(['facebook'=>'WGPP_FB_Reports','instagram'=>'WGPP_IG_Reports'] as $key=>$class){
            try{$r=$class::request($company,$ranges);$out['channels'][$key]=($r['status'] ?? '')==='complete'?$r:['status'=>'unavailable','message'=>'Exact-range reporting was not complete when this review was requested.'];}catch(Throwable $e){$out['channels'][$key]=['status'=>'unavailable'];}
        }
        try{$r=WGPP_CC_Reports::request($company);if(($r['status'] ?? '')==='complete'){$out['channels']['email']=['status'=>'complete','provider'=>WGPP_Mailchimp::label($company),'collected_at'=>$r['collected_at'] ?? '', 'basis'=>'Campaigns sent in each period; lifetime cumulative campaign responses, not period-only responses.'];foreach(['current','comparison'] as $side){$out['channels']['email'][$side]=WGPP_CC_Reports::summarize($r['rows'],...array_merge($ranges[$side],[$current['timezone']]));}}else{$out['channels']['email']=['status'=>'unavailable'];}}catch(Throwable $e){$out['channels']['email']=['status'=>'unavailable'];}
        $out=array_merge($out,WGPP_Documents::capture($company));
        $url=$out['website'];$parts=is_string($url)?wp_parse_url($url):null;$out['website_evidence']=['status'=>'unavailable','url'=>$url];
        if($parts && ($parts['scheme'] ?? '')==='https' && empty($parts['user']) && empty($parts['pass']) && empty($parts['port'])){
            $r=wp_safe_remote_get($url,['timeout'=>8,'redirection'=>0,'limit_response_size'=>262144,'headers'=>['Accept'=>'text/html']]);
            if(!is_wp_error($r) && wp_remote_retrieve_response_code($r)===200 && stripos(wp_remote_retrieve_header($r,'content-type'),'text/html')!==false){
                $html=wp_remote_retrieve_body($r);$html=preg_replace('~<(script|style|nav|footer)\b[^>]*>.*?</\1>~is',' ',$html);$text=html_entity_decode(wp_strip_all_tags($html),ENT_QUOTES|ENT_HTML5,'UTF-8');$text=preg_replace('/\s+/u',' ',$text);$out['website_evidence']=['status'=>'available','url'=>$url,'text'=>preg_replace('/^(.{0,12000}).*$/us','$1',$text),'captured_at'=>gmdate('c')];
            }
        }
        return $out;
    }
    public static function analytical($s){
        $a=$s['analysis'];$m=$a['metrics'];$prior=$s['comparison']['metrics'];$events=$m['form_events']!==null&&$m['phone_events']!==null?$m['form_events']+$m['phone_events']:null;$previous=$prior['form_events']!==null&&$prior['phone_events']!==null?$prior['form_events']+$prior['phone_events']:null;
        $fmt=static function($v){return $v===null?'unavailable':number_format((float)$v,1).'%';};
        $traffic=$a['vertical'];$eff=$a['goal_change'];$horizontal=$a['horizontal'];
        $findings=[['title'=>'Traffic and goal delivery','evidence'=>'Sessions changed '.$fmt($traffic).'; completed form and phone events changed '.$fmt(WGPP_Analytics::percent($events,$previous)).'. Goal events per 100 sessions: '.($a['goal_rate']===null?'unavailable':number_format($a['goal_rate'],2)).' (previous '.($a['prior_goal_rate']===null?'unavailable':number_format($a['prior_goal_rate'],2)).').','implication'=>$eff===null?'The baseline does not support a percentage comparison. Assess the absolute counts before drawing a growth conclusion.':($eff<0?'Goal events are not keeping pace with sessions. Prioritize the path from visit to enquiry.':'Goal delivery per session has improved. Protect the successful path and test whether it holds.')],['title'=>'Acquisition and retention balance','evidence'=>'New users: '.($m['new_users'] ?? 'unavailable').'; returning users: '.($m['returning_users'] ?? 'unavailable').'. Returning-to-new ratio changed '.$fmt($horizontal).'.','implication'=>$horizontal===null?'A zero or missing baseline prevents a reliable directional ratio.':($horizontal<0?'The audience balance is shifting toward acquisition. Test reasons for customers to return; this alone does not prove lost loyalty.':'The audience balance is shifting toward returning users. Sustain return visits while keeping new-customer discovery visible.')]];
        $actions=[];
        $add=static function($title,$where,$why,$what,$measure,$timing)use(&$actions){$actions[]=['title'=>$title,'where'=>$where,'why'=>$why,'act'=>$what,'check'=>$measure,'timing'=>$timing,'look'=>$why];};
        if($eff===null || $eff<0){$add('Make the next action easier','Website · top entry pages and contact path','Goal events per 100 sessions are '.($eff===null?'not comparable.':'down '.$fmt(abs($eff)).'.'),'Audit phone links, forms, mobile layout, and message continuity from the source to the landing page. Test one clearer service promise, one proof point, and a visible call to action.','Goal events per 100 sessions, with forms and calls tracked separately. Verify event firing before interpreting the test.','First 7 days');}else{$add('Protect the improving enquiry path','Website · high-traffic service pages','Goal delivery per session has improved.','Identify the clearest service message and action path on the pages receiving traffic. Retain that pattern and test one adjacent page before expanding it.','Goal events per 100 sessions and event counts across a comparable period.','Next 14 days');}
        $add($horizontal!==null&&$horizontal<0?'Give existing customers a reason to return':'Maintain discovery and return messaging','Email and social · link back to the Brand hub','Returning-to-new balance changed '.$fmt($horizontal).'.','Test a useful follow-up message: a maintenance reminder, customer question, or service checklist. Connect it to a relevant website page with a consistent promise and a single next action.','Returning users and tagged website visits; evaluate website goal events separately from platform engagement.','Next 14–30 days');
        $sources=array_values(array_filter($a['sources'] ?? [],static function($r){return !in_array(strtolower($r['name'] ?? ''),['(direct) / (none)','(not set)'],true);}));if($sources){$source=$sources[0]['name'] ?? $sources[0]['source_medium'] ?? $sources[0]['source'] ?? 'highest-volume source';$add('Align the strongest traffic source with the landing message','Website and '.$source,'The highest-volume source is the first place to examine message continuity. Volume alone does not establish lead quality.','Compare the entry message with the website headline, service-area wording, proof, and call to action. Test one change and retain the same comparison window.','Source sessions plus goal events where attribution is available. Avoid attributing all enquiries to that source.','Next 14 days');}
        $content_added=false;foreach(($s['context']['channels'] ?? []) as $channel=>$data){
            if(!in_array($channel,['facebook','instagram'],true)||($data['status'] ?? '')!=='complete'){continue;}
            $views=$data['current']['views']['total'] ?? null;$prior_views=$data['comparison']['views']['total'] ?? null;
            $findings[]=['title'=>ucfirst($channel).' attention','evidence'=>'Platform views: '.($views===null?'unavailable':number_format($views)).'; previous: '.($prior_views===null?'unavailable':number_format($prior_views)).'; change: '.$fmt(WGPP_Analytics::percent($views,$prior_views)).'. Net followers: '.($data['current']['followers']['net'] ?? 'unavailable').'.','implication'=>'Platform attention is a separate signal from website enquiries. Check whether the post message and destination invite a useful next step.'];
            if(!$content_added && !empty($data['posts']['top'][0]['text'])){$post=$data['posts']['top'][0];$title=preg_replace('/^(.{0,100}).*$/us','$1',$post['text']);$add('Test the strongest observed content theme',ucfirst($channel).' · content linked to a relevant service page','The highest-view published post in the available ranking begins: “'.$title.'…” ('.($post['views'] ?? 'unavailable').' lifetime views).','Use that topic as a test, with a clear service benefit, credible proof, and a relevant next action. Keep the Brand promise consistent with the linked page. Treat this as a content hypothesis; lifetime views do not establish enquiries or campaign effectiveness.','Compare platform views and tagged website visits; assess form and phone events separately.','Next 14 days');$content_added=true;}
        }
        $add('Build a dimensional messaging campaign','Message Matrix and publishing calendar','A coherent Brand needs related useful messages across discovery and return channels.','Map one audience vertical to a useful topic bucket and distinct roles for Facebook, Instagram, the /blog/ hub and email where connected. Develop a related sequence; reframe weaker hooks instead of repeating them unchanged. Use actual content results to choose the next focus.','Compare like-age post visibility and available engagement, then tagged hub visits and goal events. The existing calendar is not supplied.','Next 14–30 days');
        return self::foundation_review($s,['mode'=>'Pro Analytics Review','generation_method'=>'analytical','summary'=>($traffic!==null&&$traffic>=0?'Traffic is growing. ':'Traffic is below the comparison period or lacks a usable baseline. ').($eff!==null&&$eff<0?'Enquiry efficiency is declining, so the immediate priority is converting the available audience into completed actions.':'Focus on sustaining goal delivery while testing the balance between discovery and return visits.'),'findings'=>$findings,'actions'=>$actions,'limitations'=>['This report compares the company with itself. It does not measure competitive force or prove why performance changed.','Goal events count recorded actions, not unique customers or confirmed sales. One user may complete more than one event.','GA4 excludes known bots automatically; the excluded volume is not supplied. Additional screening is not connected. Service-area filtering is not applied.','Age and gender may be unavailable or thresholded. Unknown audience values are retained.','Social post views are lifetime counts on posts published in the reporting window. Platform views and website sessions are different measures.']]);
    }
    /** Curated from the owner's SMM Pro book, chapters 1.4, 2, 4, 5.3 and 7, plus Closing the Loop. */
    public static function foundation(){
        return ['version'=>'smm-pro-foundation-2026-10-20-loop','source'=>'The Social Media Magnet Pro · chapters 1.4, 2, 4, 5.3 and 7; Closing the Loop curriculum','principles'=>[
            ['id'=>'brand_hub','title'=>'Brand hub · narrative and message harmony','principle'=>'Story, promise, beliefs and trust center the Brand. The website/blog is the content hub. A social message and its destination should reinforce the same narrative.','audit'=>'Compare actual supplied website language and post excerpts. Identify an observable match or mismatch; if the destination content is missing, mark congruence unverified. Never invent an approved Brand promise.'],
            ['id'=>'content_leadership','title'=>'Content leadership · a reason to enter the hub','principle'=>'Useful original and curated content attracts an audience through relevance, not repeated sales claims. Social hooks should invite readers to continue on a specific blog or resource permalink at the hub. SMM blog paths are /blog/.','audit'=>'Separate a service-page call to action from a useful article that earns a visit. Examine available post topics and linked content. Top lifetime views suggest a test, not proof of content effectiveness. Without page/blog metrics, do not diagnose blog performance or absence.'],
            ['id'=>'acquisition','title'=>'Acquisition spokes · attention into website visits','principle'=>'Social channels acquire readers and followers and draw them through relevant links into the hub. Followers provide an audience for future messages; platform attention alone is not the final business result.','audit'=>'Read platform views and follower movement alongside social referral sessions, separately. Do not divide mismatched lifetime views by period sessions as a conversion rate. Recommend a specific hook, permalink and website goal to test.'],
            ['id'=>'retention','title'=>'Retention spoke · email brings the audience back','principle'=>'Email nurtures a relationship and returns readers to useful content at the hub. The 2+2+2 approach gives two seconds each to recognize the sender, understand the subject, and scan the body for a reason to click. Use a recognizable person plus company, conversational text, no logo/header image, and relevant links.','audit'=>'Assess sends, opens and clicks with returning-user movement. Email opens are not website visits or sales. Without actual email creative, sender or subject evidence, recommend a 2+2+2 check and explicitly say compliance is unverified.'],
            ['id'=>'message_rhythm','title'=>'Message rhythm · harmony and serialization','principle'=>'Repeated, related topics build an identifiable message pulse. Harmony keeps one narrative across channels; serialization develops useful topics over successive messages. The Message Matrix joins audience verticals, topic buckets and channels.','audit'=>'Use available topics and dates only. A top-five post ranking is not a publishing calendar; aggregate totals do not prove cadence or a pulse. Recommend one repeatable topic sequence and a timeline check; recommend a dimensional campaign outline connecting audience verticals, content buckets and channel roles. Suggest a related sequence for the publishing calendar; do not claim the existing calendar was inspected or publish content.'],
            ['id'=>'goal_funnel','title'=>'Goal funnel · close the loop at the hub','principle'=>'The path is attention to website visit to a designated goal, then relationship and retention. Content and links should move a reader through that path. Measure each available step and improve the weak handoff.','audit'=>'For this model only completed form and phone events are goal events. Use events per 100 sessions; not unique leads, customers, sales or percentage of users converted. Calls may rise while forms fall: preserve the distinction. Without step-level events, identify a funnel measurement gap, not a proven abandonment point.'],
            ['id'=>'loop_balance','title'=>'Infinity loop · acquisition and retention balance','principle'=>'The model represents movement toward or away from the Brand and the balance between acquiring and retaining an audience. A stronger magnet combines attraction, return visits and goal delivery.','audit'=>'In this reporting model sessions set up/down; returning-to-new balance sets left/right; goal events per 100 sessions indicate delivery efficiency. Explain all three separately. These self-comparison proxies do not measure market size, market share, actual customer loss or competitive force. Directional emphasis is a recommendation, not measured effort.']
        ]];
    }
    public static function foundation_review($s,$review){
